chrome.runtime.onMessage.addListener(function (msg, _sender, sendResponse) {
  if (msg.type !== 'GET_COIN_SYMBOL') {
    sendResponse(null);
    return;
  }
  sendResponse(extractSymbol(window.location.href));
});

function extractSymbol(url) {
  var m;

  // --- Trading sites: extract symbol or pair from URL path/query ---
  // All patterns use (?:[a-z-]+\/)? to handle optional locale prefixes
  // (e.g. /en/, /zh/, /ja/, /en-eu/, /eea/, /ko/, /tr/ etc.)

  // Binance spot: /{locale}/trade/BASE_QUOTE
  m = url.match(/binance\.com\/[a-z-]+\/trade\/([A-Z0-9]+)_[A-Z0-9]+/i);
  if (m) return m[1].toUpperCase();

  // Binance futures: /{locale}/futures/BASEQUOTE (pair_symbols lookup in popup.js)
  m = url.match(/binance\.com\/[a-z-]+\/futures\/([A-Z0-9]+)/i);
  if (m) return m[1].toUpperCase();

  // TradingView chart: ?symbol=EXCHANGE:BASEQUOTE or ?symbol=BASEQUOTE
  m = url.match(/[?&]symbol=(?:[A-Z0-9_]+:)?([A-Z0-9]+)/i);
  if (m) return m[1].toUpperCase();

  // TradingView symbols page: /symbols/PAIR/ - strip quote currency to get base
  m = url.match(/tradingview\.com\/symbols\/([A-Z0-9]+)/i);
  if (m) {
    var pair = m[1].toUpperCase();
    var base = pair.replace(/^(.+?)(USDT|USDC|BUSD|FDUSD|TUSD|USD|BTC|ETH|EUR|GBP|TRY|BRL|AUD|JPY)$/, '$1');
    if (base && base !== pair) return base;
    return resolveSlug(pair.toLowerCase()) || pair;
  }

  // Bybit: /{locale}/trade/{type}/BASE/QUOTE or /trade/{type}/BASE/QUOTE
  m = url.match(/bybit\.com\/(?:[a-z-]+\/)?trade\/[a-z]+\/([A-Z0-9]+)/i);
  if (m) return m[1].toUpperCase();

  // OKX: /{locale}/trade-{type}/base-quote
  m = url.match(/okx\.com\/(?:[a-z-]+\/)?trade-[a-z]+\/([A-Z0-9]+)-/i);
  if (m) return m[1].toUpperCase();

  // Coinbase advanced trade: /advanced-trade/{type}/BASE-QUOTE
  m = url.match(/coinbase\.com\/advanced-trade\/[a-z]+\/([A-Z0-9]+)-/i);
  if (m) return m[1].toUpperCase();

  // Coinbase price page: /price/{slug} (slug lookup)
  m = url.match(/coinbase\.com\/price\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  // Kraken Pro: /app/trade/base-quote
  m = url.match(/pro\.kraken\.com\/app\/trade\/([A-Z0-9]+)-/i);
  if (m) return m[1].toUpperCase();

  // Bitget: /{locale}/spot/BASEQUOTE (pair_symbols lookup)
  m = url.match(/bitget\.com\/(?:[a-z-]+\/)?spot\/([A-Z0-9]+)/i);
  if (m) return m[1].toUpperCase();

  // KuCoin trade: /{locale}/trade/BASE-QUOTE
  m = url.match(/kucoin\.com\/(?:[a-z-]+\/)?trade\/([A-Z0-9]+)-[A-Z0-9]+/i);
  if (m) return m[1].toUpperCase();

  // KuCoin price: /{locale}/price/SYMBOL (symbol directly in URL)
  m = url.match(/kucoin\.com\/(?:[a-z-]+\/)?price\/([A-Z0-9]+)/i);
  if (m) return m[1].toUpperCase();

  // Gate.io / Gate.com: /{locale}/trade/BASE_QUOTE
  m = url.match(/gate\.(?:com|io)\/(?:[a-z-]+\/)?trade\/([A-Z0-9]+)_[A-Z0-9]+/i);
  if (m) return m[1].toUpperCase();

  // MEXC: /{locale}/exchange/BASE_QUOTE
  m = url.match(/mexc\.com\/(?:[a-z-]+\/)?exchange\/([A-Z0-9]+)_[A-Z0-9]+/i);
  if (m) return m[1].toUpperCase();

  // HTX: /{locale}/trade/base_quote
  m = url.match(/htx\.com\/(?:[a-z-]+\/)?trade\/([A-Z0-9]+)_[A-Z0-9]+/i);
  if (m) return m[1].toUpperCase();

  // Crypto.com trade: /{locale}/exchange/trade/{type}/BASE_QUOTE
  m = url.match(/crypto\.com\/(?:[a-z-]+\/)?exchange\/trade\/[a-z]+\/([A-Z0-9]+)_[A-Z0-9]+/i);
  if (m) return m[1].toUpperCase();

  // Crypto.com price page: /{locale}/price/{slug} (slug lookup)
  m = url.match(/crypto\.com\/(?:[a-z-]+\/)?price\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  // Phemex: /trade/BASE-QUOTE
  m = url.match(/phemex\.com\/trade\/([A-Z0-9]+)-[A-Z0-9]+/i);
  if (m) return m[1].toUpperCase();

  // Phemex legacy: /spot/trade/BASEQUOTE (pair_symbols lookup)
  m = url.match(/phemex\.com\/spot\/trade\/([A-Z0-9]+)/i);
  if (m) return m[1].toUpperCase();

  // BingX: /{locale}/spot/BASEQUOTE/ (pair_symbols lookup)
  m = url.match(/bingx\.com\/[a-z-]+\/spot\/([A-Z0-9]+)/i);
  if (m) return m[1].toUpperCase();

  // Bitfinex: /t/BASE:QUOTE or /t/BASEQUOTE
  m = url.match(/trading\.bitfinex\.com\/t\/([A-Z0-9]+)[:/]/i);
  if (m) return m[1].toUpperCase();

  // dYdX: /trade/BASE-USD (supports both dydx.exchange and dydx.trade)
  m = url.match(/dydx\.(?:exchange|trade)\/trade\/([A-Z0-9]+)-/i);
  if (m) return m[1].toUpperCase();

  // --- Info/analytics sites: extract slug, resolve via SLUG_TO_SYMBOL ---

  // CoinGecko: /{lang}/coins/{slug}
  m = url.match(/coingecko\.com\/[a-z]+\/coins\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  // CoinMarketCap: /{locale}/currencies/{slug}/ or /currencies/{slug}/
  m = url.match(/coinmarketcap\.com\/(?:[a-z-]+\/)?currencies\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  // CoinDesk: /price/{slug}
  m = url.match(/coindesk\.com\/price\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  // CryptoCompare: /coins/{symbol}/overview/QUOTE - symbol directly in URL
  m = url.match(/cryptocompare\.com\/coins\/([a-z0-9]+)\//i);
  if (m) return m[1].toUpperCase();

  // Messari: /project/{slug}
  m = url.match(/messari\.io\/project\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  // DeFiLlama: /protocol/{slug} or /chain/{slug}
  m = url.match(/defillama\.com\/(?:protocol|chain)\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  // Kraken prices: /prices/{slug}
  m = url.match(/kraken\.com\/prices\/([a-z0-9-]+)/i);
  if (m) return resolveSlug(m[1]);

  return null;
}

function resolveSlug(slug) {
  var lower = slug.toLowerCase();
  return SLUG_TO_SYMBOL[lower] || null;
}
